mapper.select:
SELECT FROM ai_knowledge_document WHERE del_flag = '0'
AND knowledge_id = #{knowledgeId}
AND doc_name LIKE CONCAT('%', #{docName}, '%')
AND process_status = #{processStatus}
ORDER BY create_time DESC

SELECT COUNT(1)
FROM ai_knowledge_document
WHERE knowledge_id = #{knowledgeId}
  AND content_hash = #{contentHash}
  AND del_flag = '0'

  AND id != #{excludeId}

mapper.update:
UPDATE ai_knowledge_document
SET process_status = #{processStatus},
    update_time = CURRENT_TIMESTAMP, process_error = #{processError}

    , chunk_count = #{chunkCount}

WHERE id = #{id} AND del_flag = '0' AND process_attempt = #{attempt}
  AND process_status = #{expectedStatus}
  AND (#{processStatus} != 'success' OR process_deadline > CURRENT_TIMESTAMP)
